// Input array of words
const words = ["skyscraper", "chair", "umbrella", "curtain"];

// Function to process the words and convert to JSON format
function organizeWordsByLength(words) {
    // Array to hold the result
    const organizedArray = [];

    // Iterate over each word
    for (let i = 0; i < words.length; i++) {
        let word = words[i];

        // Calculate the length of the current word
        let length = word.length;

        // Create an object containing the word and its length
        organizedArray.push({ word: word, length: length });
    }

    // Convert the array of objects to a JSON string
    return JSON.stringify(organizedArray);
